#include <bits/stdc++.h>
using namespace std;

long long power_mod(long long base, long long exp, long long mod) {
    long long res = 1;
    long long cur = base % mod;
    while (exp > 0) {
        if (exp & 1) res = (res * cur) % mod;
        cur = (cur * cur) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m;
    cin >> n >> m;
    if (m == 0) {
        cout << power_mod(n, n - 1, 1000000007) << "\n";
    } else if (m == 1) {
        cout << power_mod(n, n, 1000000007) << "\n";
    } else {
        vector<long long> parent(n + 1);
        vector<long long> size(n + 1, 0);
        for (long long i = 0; i <= n; ++i) parent[i] = i;

        function<long long(long long)> find_set = [&](long long x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };

        auto union_sets = [&](long long a, long long b) {
            long long pa = find_set(a);
            long long pb = find_set(b);
            if (pa != pb) {
                parent[pb] = pa;
            }
        };

        for (long long i = 1; i < n; ++i) {
            long long b = (i * m) % n;
            union_sets(i, b);
        }

        set<long long> unique_parents;
        for (long long i = 1; i < n; ++i) {
            unique_parents.insert(find_set(i));
        }
        long long count = (long long)unique_parents.size();
        cout << power_mod(n, count, 1000000007) << "\n";
    }
    return 0;
}
